const $=s=>document.querySelector(s),sleep=ms=>new Promise(r=>setTimeout(r,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const button=(i,a)=>`[data-deck="${i}"][data-action="${a}"]`,click=s=>{assert($(s),'Missing '+s);$(s).click();};
const files=['app.js','engine.js','stems.js','panels.js','keylock-shadow-live.js','sync-tempo-handoff.js','stem-commit-ui-harness.js','stem-activation-capture-145.js','vendor/signalsmith-stretch/SignalsmithStretch-open-play-replace.mjs'];
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(x=>x.toString(16).padStart(2,'0')).join('');
async function identities(){return Object.fromEntries(await Promise.all(files.map(async f=>{const r=await fetch(f,{cache:'no-store'});assert(r.ok,'Missing '+f);return[f,await hash(await r.arrayBuffer())];})));}
async function until(fn,label,ms=30000){const end=performance.now()+ms;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(5);}}
function base64(bytes){let s='';for(let i=0;i<bytes.length;i+=16384)s+=String.fromCharCode(...bytes.subarray(i,i+16384));return btoa(s);}
let app;
async function run(){
 const {engine,state}=app,decks=state.decks.slice(0,2),track=decks[0].track,witnesses=[],captureAudio=new URL(location.href).searchParams.has('capture');
 const r={checkpoint:149,startedAt:new Date().toISOString(),captureAudio,scope:'Actual local Prepare/API/completed SCNet cache/decode mixed-deck activation, actual Cancel before commit and native disabled Cancel after commit, all-pad mute/restore/Stop. Owned8second330/550Hz tone, physical mute. No new inference, music/native/hardware/reference acceptance.',criteria:{captureSeconds:4,minimum10msRMSRatio:.85,maximumAdjacentJump:.03,maximumNearZeroRunSeconds:.001,nearZeroAbsolute:1e-7,maximumMutedPeak:1e-7},progress:[],errors:[]};let recording,adapter,oldEvent,oldSet,oldAttach,latestSignal;
 function capture(){return Promise.all(witnesses.map(w=>new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('PCM timeout')),14000);w.port.onmessage=({data})=>{if(data.type==='done'){clearTimeout(timer);resolve(data);}};w.port.postMessage({type:'capture',id:'commit',frames:Math.round(4*engine.ctx.sampleRate)});})));}
 async function retain(packets){return Promise.all(packets.map(async(p,i)=>({deck:Math.floor(i/2),channel:i%2,startFrame:p.startFrame,frames:p.data.length,quanta:p.quanta,errors:p.errors,sha256:await hash(p.data.buffer),base64:base64(new Uint8Array(p.data.buffer))})));}
 $('#commit-run').disabled=true;
 try{
  r.sourceBefore=await identities();engine.init();engine.audioMonitor.mutePhysical(true);await engine.resume();assert(engine.audioMonitor.snapshot().physicalMuted,'Physical mute');await until(()=>!state.analysis,'Analysis');for(const d of state.decks)engine.pause(d);
  for(const unit of state.fx)for(const slot of unit)slot.on=false;engine.configureFX(state.fx,state.fxRoutes||[],state.decks.map(d=>(d.track?.bpm||120)*d.rate),state.fxTempo);
  const sr=44100,original=engine.ctx.createBuffer(2,sr*8,sr);for(let c=0;c<2;c++)for(let n=0;n<original.length;n++)original.getChannelData(c)[n]=.12*Math.sin(2*Math.PI*(c?550:330)*n/sr);
  Object.assign(track,{duration:8,bpm:120,grid:0,gridWarpMarkers:[],gridMarkers:[],analyzed:true});delete track.stemJob;engine.buffers.set(track.id,original);engine.stemBuffers.delete(track.id);state.selected=track.id;
  r.originalHashes=await Promise.all([0,1].map(c=>hash(original.getChannelData(c).buffer)));r.sampleRate=engine.ctx.sampleRate;
  for(const [i,d]of decks.entries()){Object.assign(d,{track,position:0,rate:1.1,keylock:i===0,keyShift:0,reverse:false,loop:false,slip:false,stemSlip:'off',sync:false,mode:'INT',stems:[true,true,true,true],stemFX:[false,false,false,false]});engine.clearDeckScratchCache(i);engine.mix(i,'level',.5);}
  if(captureAudio){await engine.ctx.audioWorklet.addModule(new URL('./stem-activation-capture-145.js',import.meta.url));for(let i=0;i<2;i++){const split=engine.ctx.createChannelSplitter(2);engine.nodes[i].monitorTap.connect(split);for(let c=0;c<2;c++){const w=new AudioWorkletNode(engine.ctx,'open-play-stem-activation-145-test',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[1],channelCount:1,channelCountMode:'explicit',channelInterpretation:'discrete'});split.connect(w,c);w.connect(engine.ctx.destination);witnesses.push(w);}}}
  for(let i=0;i<2;i++){click(button(i,'tab')+'[data-tab="Stems"]');click(button(i,'play'));await until(()=>decks[i].playing&&!decks[i].processing,'Play '+i);}
  const voices=decks.map(d=>engine.voices.get(d.index));adapter=voices[0].liveKeylock;assert(adapter?.reservedStems&&!voices[1].liveKeylock,'Mixed owners');r.initialLive=adapter.snapshot();await sleep(200);
  click(button(0,'stemPrepare'));const output=$('#stems-state');const progress=new MutationObserver(()=>r.progress.push({at:engine.ctx.currentTime,text:output.textContent,cancelDisabled:$('#stems-cancel').disabled}));progress.observe(output,{childList:true,subtree:true,characterData:true});
  oldEvent=adapter.onEvent;r.precommit={clicked:false};adapter.onEvent=e=>{oldEvent(e);if(e.type==='stem-bank-warming'&&!r.precommit.clicked){r.precommit.clicked=true;r.precommit.at=engine.ctx.currentTime;r.precommit.status=output.textContent;r.precommit.cancelEnabled=!$('#stems-cancel').disabled;click('#stems-cancel');}};
  click('#stems-queue');await until(()=>r.precommit.clicked&&!$('#stems-queue').disabled&&track.stemState.startsWith('Cancelled'),'Actual warm-up Cancel');adapter.onEvent=oldEvent;oldEvent=null;r.precommit.sameOwners=decks.map((d,i)=>engine.voices.get(d.index)===voices[i]);r.precommit.cacheAbsent=!engine.stemBuffers.has(track.id);assert(r.precommit.cancelEnabled&&r.precommit.sameOwners.every(Boolean)&&r.precommit.cacheAbsent,'Warm-up cancellation changed playback');
  oldAttach=engine.attachStems;engine.attachStems=async function(...args){latestSignal=args[3]?.signal;const result=await oldAttach.apply(this,args);r.attachReturnedAt=this.ctx.currentTime;return result;};
  oldSet=engine.stemBuffers.set;engine.stemBuffers.set=function(key,value){const result=oldSet.call(this,key,value);if(key===track.id&&!r.commitQueued){r.commitQueued=true;r.committedAt=engine.ctx.currentTime;queueMicrotask(()=>{const cancel=$('#stems-cancel');r.committed={at:engine.ctx.currentTime,status:output.textContent,cancelDisabled:cancel.disabled,queueDisabled:$('#stems-queue').disabled,clearDisabled:$('#stems-clear').disabled,handoffUntil:engine.voices.get(1).handoffBefore?.until,clickEvents:0};const listener=()=>r.committed.clickEvents++;cancel.addEventListener('click',listener);cancel.click();cancel.removeEventListener('click',listener);r.committed.signalAbortedAfterClick=latestSignal.aborted;});}return result;};
  if(captureAudio){recording=capture();await sleep(200);}r.retryStartedAt=engine.ctx.currentTime;click('#stems-queue');$('#commit-status').textContent='Running actual preparation and handover controls…';
  await until(()=>!$('#stems-queue').disabled&&track.stemState.startsWith('Ready'),'Actual Ready');assert(r.committed,'Commit UI not observed');r.readyAt=engine.ctx.currentTime;r.ready={status:output.textContent,cancelDisabled:$('#stems-cancel').disabled,queueDisabled:$('#stems-queue').disabled,clearDisabled:$('#stems-clear').disabled,model:track.stemModel,job:track.stemJob,playing:decks.map(d=>d.playing),sameOwners:decks.map((d,i)=>engine.voices.get(d.index)===voices[i])};
  const jobResponse=await fetch('/api/stems/'+track.stemJob);assert(jobResponse.ok,'Actual job');r.job=await jobResponse.json();assert(r.job.state==='complete'&&r.job.model==='SCNet-large official','Completed real SCNet cache');
  await sleep(100);click('#modal-close');r.muteAt=engine.ctx.currentTime;for(let i=0;i<2;i++)for(let p=0;p<4;p++)click(button(i,'pad')+`[data-pad="${p}"]`);r.muted=decks.map(d=>[...d.stems]);await sleep(250);r.restoreAt=engine.ctx.currentTime;for(let i=0;i<2;i++)for(let p=0;p<4;p++)click(button(i,'pad')+`[data-pad="${p}"]`);await sleep(250);r.stopAt=engine.ctx.currentTime;for(let i=0;i<2;i++)click(button(i,'play'));await until(()=>decks.every(d=>!d.playing),'Stop');
  if(recording)r.pcm=await retain(await recording);progress.disconnect();r.originalUnchanged=JSON.stringify(r.originalHashes)===JSON.stringify(await Promise.all([0,1].map(c=>hash(original.getChannelData(c).buffer))));assert(r.originalUnchanged,'Original mutated');r.workflowExecuted=true;
 }catch(error){r.errors.push({message:error.message,stack:error.stack});if(recording&&!r.pcm)try{r.pcm=await retain(await recording);}catch(e){r.errors.push({captureError:e.message});}}
 finally{if(adapter&&oldEvent)adapter.onEvent=oldEvent;if(oldSet)engine.stemBuffers.set=oldSet;if(oldAttach)engine.attachStems=oldAttach;for(const d of state.decks)engine.pause(d);for(const w of witnesses){w.disconnect();w.port.close();}r.sourceAfter=await identities();r.sourceStable=JSON.stringify(r.sourceBefore)===JSON.stringify(r.sourceAfter);r.workflowCompleted=!!r.workflowExecuted&&!r.errors.length&&r.sourceStable;r.controlsPassed=!!(r.workflowCompleted&&r.committed.cancelDisabled&&r.committed.queueDisabled&&r.committed.clearDisabled&&!r.committed.signalAbortedAfterClick&&r.committed.clickEvents===0&&r.committed.status.startsWith('Finishing audio handover')&&!r.ready.cancelDisabled&&!r.ready.queueDisabled&&!r.ready.clearDisabled&&r.attachReturnedAt>=r.committed.handoffUntil+.01);r.finishedAt=new Date().toISOString();$('#commit-original').textContent=JSON.stringify(r);$('#commit-results').textContent=JSON.stringify({...r,pcm:r.pcm?.map(({base64,...p})=>p)},null,2);$('#commit-status').textContent=r.workflowCompleted?(r.controlsPassed?'Preparation controls passed; stopped; independent audio inspection required':'Preparation controls FAILED; original retained; stopped'):'Failed: '+r.errors.map(e=>e.message).join('; ');}
}
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[0].track,'Actual app');app=window.openPlay;$('#commit-run').disabled=false;$('#commit-status').textContent='Ready';}
$('#commit-run').onclick=()=>run();boot().catch(e=>$('#commit-status').textContent=e.message);
